import { escapeHtml as esc } from './message-format.js';
const step = (name='Review request', extra={}) => ({name,instructions:'',group:'',approval:false,checklist:[],...extra});
const fresh = () => ({id:0n,name:'',description:'',enabled:true,fields:[],priority:'normal',respondH:24n,resolveH:0n,steps:[step(),step('Resolve request')]});
const clone = value => structuredClone(value);
export function refundTemplate() {
  return {...fresh(),name:'Refund request',description:'Ask us to review a purchase for a refund.',fields:[{key:'order_id',title:'Order number',kind:'text',required:true,sensitive:false,options:[]}],steps:[step('Support review',{instructions:'Review the order and the applicable refund policy.',checklist:['Order verified','Eligibility reviewed']}),step('Refund approval',{approval:true,instructions:'Confirm whether the refund is approved. Send back for clarification or cancel with a reason.'}),step('Refund confirmation',{instructions:'Process the refund in your payment system, then reply to the customer. Desk does not transfer money.',checklist:['Refund recorded in the payment system','Customer informed']})]};
}
/** Admin-only configuration. Project revision protects concurrent edits across all settings. */
export async function projectWorkflows({root,project,api,token,active,reload}) {
  const [types,teams]=await Promise.all([api().listCustomerTypes(token(),project.id),api().customerWorkflowTeams(token(),project.id)]);if(!active())return;
  const base=`#/customers/${project.id}`;
  function list() {
    root.innerHTML=`<a class="back-link" href="${base}/settings">← Project & integrations</a><div class="page-heading"><div><span class="eyebrow">${esc(project.name)} · CONFIGURATION</span><h2>Request types & workflows</h2><p class="lead">The right questions. A clear path to done.</p></div><button class="primary" id="cwNew">New request type +</button></div><div class="workflow-type-list">${types.map(t=>`<article class="card workflow-type"><div><div class="btnrow"><h3>${esc(t.name)}</h3>${t.id===project.typeId?'<span class="pill">Default</span>':''}${!t.enabled?'<span class="pill off">Intake paused</span>':''}</div><p>${esc(t.description)}</p><div class="workflow-mini">${t.steps.length?t.steps.map(s=>`<span>${s.approval?'◇ ':''}${esc(s.name)}</span>`).join('<b aria-hidden="true">→</b>'):'<span>Standard support · receive, work, resolve</span>'}</div><p class="kv">API type ID: <code>${t.id}</code>${project.widgetEnabled&&project.enabled&&t.enabled?` · <a href="./support.html#form/${project.widgetId}/${t.id}" target="_blank" rel="noopener noreferrer">Preview this form ↗</a>`:''}</p></div><button data-edit="${t.id}">Edit type</button></article>`).join('')}</div><div class="card workflow-starter"><div><h3>A useful starting point</h3><p>Refunds: review the purchase, approve the refund, confirm it was processed.</p></div><button id="cwRefund">Use refund template</button></div><p class="kv">Changes apply to new requests. Active tickets keep their original fields and workflow. The default type is used when an integration omits typeId.</p>`;
    root.querySelector('#cwNew').onclick=()=>editor(fresh());root.querySelector('#cwRefund').onclick=()=>editor(refundTemplate());root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(clone(types.find(t=>String(t.id)===b.dataset.edit))));
  }
  function editor(t) {
    const input=(id,label,value,attrs='')=>`<label for="${id}">${label}</label><input id="${id}" ${attrs.includes('type=')?'':'type="text"'} value="${esc(value)}" ${attrs}>`;
    root.innerHTML=`<button class="back-link" id="cwBack">← Request types</button><div class="page-heading"><div><span class="eyebrow">${esc(project.name)} · REQUEST TYPE</span><h2>${t.id?'Edit request type':'Create a request type'}</h2><p class="lead">Customers choose the type. Your team follows the steps.</p></div></div><datalist id="cwHubGroups">${teams.map(t=>`<option value="${esc(t.name)}">${t.eligible} project agents</option>`).join('')}</datalist><form id="cwForm"><section class="card customer-section"><h3>01 · What customers see</h3>${input('cwName','Request type name',t.name,'required maxlength="60" placeholder="e.g. Refund request"')}<label for="cwDescription">Short description</label><textarea id="cwDescription" maxlength="300" rows="2">${esc(t.description)}</textarea><p class="kv">Name, email, subject and message are always included.</p><div id="cwFields"></div><button type="button" id="cwAddField">Add a field +</button></section><section class="card customer-section"><div class="page-heading"><div><h3>02 · How your team handles it</h3><p class="kv">Steps run in order. Required checks must be done before moving on.</p></div></div><div id="cwSteps"></div><button type="button" id="cwAddStep">Add a step +</button><p class="kv">Leave the responsible group blank for the whole project team. A named Hub group also needs Desk Agent and project access. Hub owners and Desk admins can handle every step.</p></section><section class="card customer-section"><h3>03 · Service targets</h3><div class="row"><div><label for="cwPriority">Starting priority</label><select id="cwPriority">${['low','normal','high','urgent'].map(v=>`<option ${v===t.priority?'selected':''}>${v}</option>`).join('')}</select></div><div>${input('cwRespond','First response · hours',t.respondH,'type="number" min="0" max="8760" required')}</div><div>${input('cwResolve','Resolution · hours',t.resolveH,'type="number" min="0" max="8760" required')}</div></div><p class="kv">Elapsed hours from submission. Use 0 for no target.</p>${t.id!==project.typeId?`<label class="checkline"><input id="cwEnabled" type="checkbox" ${t.enabled?'checked':''}> Accept new requests of this type</label>`:'<p class="kv">This is the default type. It stays available for existing integrations.</p>'}</section><div class="btnrow"><button type="submit" class="primary">Save request type</button><button type="button" id="cwCancel">Cancel</button><span id="cwStatus" role="status"></span></div><p class="kv">Saving affects new requests only. No payments or external actions run automatically.</p></form>`;
    const fields=root.querySelector('#cwFields'),steps=root.querySelector('#cwSteps');
    function paintFields(){fields.innerHTML=t.fields.map((f,i)=>`<div class="customer-field" data-field="${i}"><div>${input(`cwfl${i}`,'Label',f.title,'data-field-prop="title" required maxlength="80"')}</div><div>${input(`cwfk${i}`,'API field key',f.key,'data-field-prop="key" required pattern="[a-z0-9_]+" maxlength="40"')}</div><div><label for="cwft${i}">Type</label><select id="cwft${i}" data-field-prop="kind">${[['text','Short text'],['textarea','Long text'],['select','Choice'],['date','Date'],['bool','Yes / no']].map(([v,l])=>`<option value="${v}" ${v===f.kind?'selected':''}>${l}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" data-field-prop="required" ${f.required?'checked':''}> Required</label><button type="button" data-remove-field="${i}" aria-label="Remove field ${i+1}">×</button><div class="customer-options ${f.kind==='select'?'':'hidden'}">${input(`cwfo${i}`,'Choices · comma separated',f.options.join(', '),'data-field-prop="options"')}</div></div>`).join('');root.querySelector('#cwAddField').disabled=t.fields.length>=12;}
    const teamHint=group=>!group.trim()?'':Number(teams.find(t=>t.name===group.trim())?.eligible||0)>0?`${teams.find(t=>t.name===group.trim()).eligible} project agent(s) in this Hub group.`:'No eligible project agents in this group. Only Hub admins can progress until roles and group membership are set in Hub.';
    function paintSteps(){steps.innerHTML=t.steps.map((s,i)=>`<article class="workflow-editor-step" data-step="${i}"><div class="workflow-step-heading"><span class="workflow-number">${i+1}</span><strong>${s.approval?'Approval':'Work step'}</strong><div class="btnrow"><button type="button" data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Move step ${i+1} up">↑</button><button type="button" data-move="${i}" data-dir="1" ${i===t.steps.length-1?'disabled':''} aria-label="Move step ${i+1} down">↓</button><button type="button" data-remove-step="${i}" aria-label="Remove step ${i+1}">Remove</button></div></div><div class="row"><div>${input(`cwsn${i}`,'Step name',s.name,'data-step-prop="name" required maxlength="60"')}</div><div>${input(`cwsg${i}`,'Responsible Hub group',s.group,'data-step-prop="group" list="cwHubGroups" maxlength="80" placeholder="Whole project team"')}<p class="kv" data-team-hint>${esc(teamHint(s.group))}</p></div></div><label class="checkline"><input type="checkbox" data-step-prop="approval" ${s.approval?'checked':''}> Require an explicit approval</label><details ${s.instructions||s.checklist.length?'open':''}><summary>Instructions & required checks${s.checklist.length?' · '+s.checklist.length:''}</summary><label for="cwsi${i}">Instructions · internal only</label><textarea id="cwsi${i}" data-step-prop="instructions" rows="2" maxlength="500">${esc(s.instructions)}</textarea><label for="cwsc${i}">Required checks · one per line, up to 8</label><textarea id="cwsc${i}" data-step-prop="checklist" rows="3">${esc(s.checklist.join('\n'))}</textarea></details></article>`).join('')||'<p class="kv">Standard support: receive, work, resolve. Add steps to make a guided workflow.</p>';root.querySelector('#cwAddStep').disabled=t.steps.length>=8;}
    fields.oninput=e=>{const row=e.target.closest('[data-field]'),k=e.target.dataset.fieldProp;if(!row||!k)return;const f=t.fields[Number(row.dataset.field)];f[k]=k==='required'?e.target.checked:k==='options'?e.target.value.split(',').map(v=>v.trim()).filter(Boolean):e.target.value;if(k==='kind')row.querySelector('.customer-options').classList.toggle('hidden',f.kind!=='select');};
    fields.onclick=e=>{const b=e.target.closest('[data-remove-field]');if(b){t.fields.splice(Number(b.dataset.removeField),1);paintFields();}};
    steps.oninput=e=>{const row=e.target.closest('[data-step]'),k=e.target.dataset.stepProp;if(!row||!k)return;const s=t.steps[Number(row.dataset.step)];s[k]=k==='approval'?e.target.checked:k==='checklist'?e.target.value.split('\n').map(v=>v.trim()).filter(Boolean):e.target.value;if(k==='approval')row.querySelector('strong').textContent=s.approval?'Approval':'Work step';if(k==='group')row.querySelector('[data-team-hint]').textContent=teamHint(s.group);};
    steps.onclick=e=>{const remove=e.target.closest('[data-remove-step]'),move=e.target.closest('[data-move]');if(remove)t.steps.splice(Number(remove.dataset.removeStep),1);else if(move){const i=Number(move.dataset.move),j=i+Number(move.dataset.dir);[t.steps[i],t.steps[j]]=[t.steps[j],t.steps[i]];}else return;paintSteps();};
    root.querySelector('#cwAddField').onclick=()=>{t.fields.push({key:'',title:'',kind:'text',required:false,sensitive:false,options:[]});paintFields();};root.querySelector('#cwAddStep').onclick=()=>{t.steps.push(step(''));paintSteps();};paintFields();paintSteps();
    root.querySelector('#cwBack').onclick=list;root.querySelector('#cwCancel').onclick=list;
    root.querySelector('#cwForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=e.submitter,notice=root.querySelector('#cwStatus');if(button.disabled)return;const value=id=>root.querySelector('#'+id).value;const payload={name:value('cwName').trim(),description:value('cwDescription').trim(),fields:t.fields,steps:t.steps,priority:value('cwPriority'),respondH:BigInt(value('cwRespond')),resolveH:BigInt(value('cwResolve')),enabled:root.querySelector('#cwEnabled')?.checked??true};button.disabled=true;notice.textContent='Saving…';try{const result=await api().saveCustomerType(token(),project.id,project.revision,t.id,payload);if(!active()||!form.isConnected)return;if(!result.ok)throw Error(result.detail);await reload();}catch(error){if(active()&&notice.isConnected)notice.textContent=error.message||'Could not confirm the save. Reload before retrying.';}finally{if(button.isConnected)button.disabled=false;}};
  }
  list();
}

/** Shows only the current step in detail; no customer data is sent to other tools. */
export function paintCustomerWorkflow({el,value,act}) {
  if(!el)return;
  if(!value){el.replaceChildren();el.classList.add('hidden');delete el.dataset.signature;return;}
  el.classList.remove('hidden');
  const {run:r,canProgress}=value,def=r.definition,current=Number(r.step),s=def.steps[current],done=!!r.outcome;
  const signature=JSON.stringify(value,(_,v)=>typeof v==='bigint'?String(v):v);if(el.dataset.signature===signature)return;el.dataset.signature=signature;
  el.innerHTML=`<div class="workflow-ticket-heading"><div><span class="eyebrow">${esc(def.name)} · WORKFLOW</span><h3>${done?(r.outcome==='completed'?'Request completed':'Request cancelled'):esc(s.name)}</h3></div><span class="pill">${done?'Finished':`Step ${current+1} of ${def.steps.length}`}</span></div><ol class="workflow-progress">${def.steps.map((x,i)=>`<li class="${i===current?'current':i<current?'done':''}" ${i===current?'aria-current="step"':''}>${i<current?'✓ ':''}${esc(x.name)}</li>`).join('')}</ol>${!done?`<p>${esc(s.instructions||'Complete this step, then continue to the next.')}</p><p class="kv">Responsible: ${esc(s.group||'Project support team')}${s.approval?' · Explicit approval required':''}</p><div class="workflow-checks">${s.checklist.map((title,i)=>`<label class="checkline"><input type="checkbox" data-workflow-check="${i}" ${r.checked[i]?'checked':''} ${!canProgress?'disabled':''}> ${esc(title)}</label>`).join('')}</div><div class="btnrow"><button class="primary" data-workflow-action="${s.approval?'approve':'advance'}" ${!canProgress||r.checked.some(x=>!x)?'disabled':''}>${s.approval?(current===def.steps.length-1?'Approve & complete':'Approve & continue'):(current===def.steps.length-1?'Complete request':'Complete step →')}</button>${!canProgress?'<span class="kv">Your Hub account is not in this step’s responsible team.</span>':''}</div>`:'<p class="kv">The conversation remains available until its scheduled deletion.</p>'}${canProgress?`<details class="workflow-exception"><summary>${done?'Reopen request':'Needs a different outcome?'}</summary><label for="workflowReason">Internal reason</label><textarea id="workflowReason" minlength="5" maxlength="500" rows="2" placeholder="Explain why this needs to change…"></textarea><div class="btnrow">${done?'<button data-workflow-action="reopen">Restart from first step</button>':`${current>0?`<button data-workflow-action="back">${s.approval?'Return for changes':'Back one step'}</button>`:''}<button data-workflow-action="cancel">Cancel request</button>`}</div><p class="kv">${done?'Previous actions stay in the activity history. All required checks start again.':'Going back clears checks for the step you return to. Cancellation closes the request and requires a reason.'}</p></details>`:''}<p id="workflowStatus" class="status" role="status"></p>`;
  el.querySelectorAll('[data-workflow-check]').forEach(box=>box.onchange=()=>act(box,'check',r.revision,BigInt(box.dataset.workflowCheck),box.checked));
  el.querySelectorAll('[data-workflow-action]').forEach(b=>b.onclick=()=>act(b,b.dataset.workflowAction,r.revision,el.querySelector('#workflowReason')?.value.trim()||''));
}
